/* ============================================================
   IBM STORAGE DASHBOARD — CSS (HTML Graphics Plugin)
   Coloque este conteúdo no campo "CSS" do painel
   ============================================================ */

* { margin: 0; padding: 0; box-sizing: border-box; }

.ibm-dashboard {
  font-family: 'IBM Plex Sans', -apple-system, sans-serif;
  background: var(--ibm-bg-deep);
  color: var(--ibm-text);
  padding: 24px;
  min-height: 100%;
  overflow-y: auto;
}

/* ---- HEADER ---- */
.ibm-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--ibm-border);
}
.ibm-header-left { display: flex; align-items: center; gap: 16px; }
.ibm-logo-icon {
  width: 48px; height: 48px;
  background: var(--ibm-gradient-blue);
  border-radius: var(--ibm-radius-sm);
  display: flex; align-items: center; justify-content: center;
  font-size: 22px; font-weight: 700; color: #fff;
  box-shadow: var(--ibm-shadow-glow);
  animation: logoPulse 3s ease-in-out infinite;
}
@keyframes logoPulse {
  0%, 100% { box-shadow: 0 0 15px rgba(99,102,241,0.3); }
  50% { box-shadow: 0 0 30px rgba(99,102,241,0.6); }
}
.ibm-header h1 {
  font-size: 22px; font-weight: 600; letter-spacing: -0.5px;
  background: var(--ibm-gradient-blue);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.ibm-header-sub { font-size: 12px; color: var(--ibm-text-dim); margin-top: 2px; }
.ibm-header-right { display: flex; align-items: center; gap: 12px; }
.ibm-status-badge {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 14px; border-radius: 20px;
  font-size: 12px; font-weight: 500;
  background: rgba(16,185,129,0.1);
  border: 1px solid rgba(16,185,129,0.3);
  color: var(--ibm-green);
}
.ibm-status-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--ibm-green);
  animation: dotBlink 2s ease-in-out infinite;
}
@keyframes dotBlink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
.ibm-status-badge.offline {
  background: rgba(244,63,94,0.1);
  border-color: rgba(244,63,94,0.3);
  color: var(--ibm-red);
}
.ibm-status-badge.offline .ibm-status-dot { background: var(--ibm-red); }
.ibm-timestamp { font-size: 11px; color: var(--ibm-text-dim); font-family: 'IBM Plex Mono', monospace; }

/* ---- KPI CARDS ---- */
.ibm-kpi-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 28px;
}
.ibm-kpi-card {
  background: var(--ibm-bg-card);
  border: 1px solid var(--ibm-border);
  border-radius: var(--ibm-radius);
  padding: 20px;
  transition: var(--ibm-transition);
  position: relative;
  overflow: hidden;
}
.ibm-kpi-card::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: var(--ibm-gradient-blue);
  opacity: 0;
  transition: opacity 0.3s;
}
.ibm-kpi-card:hover { border-color: var(--ibm-border-glow); transform: translateY(-2px); box-shadow: var(--ibm-shadow-glow); }
.ibm-kpi-card:hover::before { opacity: 1; }
.ibm-kpi-card.green::before { background: var(--ibm-gradient-green); }
.ibm-kpi-card.amber::before { background: var(--ibm-gradient-amber); }
.ibm-kpi-card.red::before { background: var(--ibm-gradient-red); }
.ibm-kpi-label { font-size: 11px; font-weight: 500; text-transform: uppercase; letter-spacing: 1px; color: var(--ibm-text-dim); margin-bottom: 8px; }
.ibm-kpi-value { font-size: 32px; font-weight: 700; font-family: 'IBM Plex Mono', monospace; line-height: 1; }
.ibm-kpi-value.blue { color: var(--ibm-blue); }
.ibm-kpi-value.green { color: var(--ibm-green); }
.ibm-kpi-value.amber { color: var(--ibm-amber); }
.ibm-kpi-value.red { color: var(--ibm-red); }
.ibm-kpi-sub { font-size: 12px; color: var(--ibm-text-muted); margin-top: 6px; }
.ibm-kpi-icon { position: absolute; top: 16px; right: 16px; font-size: 28px; opacity: 0.15; }

/* ---- SECTION ---- */
.ibm-section {
  margin-bottom: 28px;
}
.ibm-section-title {
  font-size: 15px; font-weight: 600; margin-bottom: 16px;
  display: flex; align-items: center; gap: 10px;
  color: var(--ibm-text);
}
.ibm-section-title .icon {
  width: 28px; height: 28px; border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  background: rgba(99,102,241,0.1);
  color: var(--ibm-accent);
}

/* ---- POOL GAUGE CARDS ---- */
.ibm-pools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 16px;
}
.ibm-pool-card {
  background: var(--ibm-bg-card);
  border: 1px solid var(--ibm-border);
  border-radius: var(--ibm-radius);
  padding: 24px;
  transition: var(--ibm-transition);
}
.ibm-pool-card:hover { border-color: var(--ibm-border-glow); box-shadow: var(--ibm-shadow-glow); }
.ibm-pool-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.ibm-pool-name { font-size: 16px; font-weight: 600; }
.ibm-pool-status {
  font-size: 11px; font-weight: 600; padding: 3px 10px;
  border-radius: 12px; text-transform: uppercase; letter-spacing: 0.5px;
}
.ibm-pool-status.online { background: rgba(16,185,129,0.15); color: var(--ibm-green); }
.ibm-pool-status.offline { background: rgba(239,68,68,0.15); color: var(--ibm-red); }
.ibm-gauge-container { display: flex; align-items: center; gap: 24px; margin-bottom: 16px; }
.ibm-gauge-svg { width: 110px; height: 110px; flex-shrink: 0; }
.ibm-gauge-bg { fill: none; stroke: rgba(255,255,255,0.06); stroke-width: 10; }
.ibm-gauge-fill { fill: none; stroke-width: 10; stroke-linecap: round; transition: stroke-dashoffset 1.5s cubic-bezier(0.4,0,0.2,1), stroke 0.5s; }
.ibm-gauge-text { font-family: 'IBM Plex Mono', monospace; font-size: 18px; font-weight: 700; fill: var(--ibm-text); text-anchor: middle; }
.ibm-gauge-sublabel { font-size: 9px; fill: var(--ibm-text-dim); text-anchor: middle; font-weight: 500; text-transform: uppercase; letter-spacing: 1px; }
.ibm-pool-details { flex: 1; }
.ibm-pool-detail-row { display: flex; justify-content: space-between; padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.04); font-size: 13px; }
.ibm-pool-detail-row:last-child { border-bottom: none; }
.ibm-pool-detail-label { color: var(--ibm-text-dim); }
.ibm-pool-detail-value { font-weight: 600; font-family: 'IBM Plex Mono', monospace; color: var(--ibm-text); }
.ibm-pool-bar-container { margin-top: 12px; }
.ibm-pool-bar-labels { display: flex; justify-content: space-between; font-size: 11px; color: var(--ibm-text-dim); margin-bottom: 6px; }
.ibm-pool-bar { width: 100%; height: 8px; border-radius: 4px; background: rgba(255,255,255,0.06); overflow: hidden; position: relative; }
.ibm-pool-bar-fill {
  height: 100%; border-radius: 4px;
  transition: width 1.5s cubic-bezier(0.4,0,0.2,1);
  position: relative;
}
.ibm-pool-bar-fill::after {
  content: '';
  position: absolute; top: 0; right: 0; bottom: 0; width: 30px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3));
  animation: barShimmer 2s ease-in-out infinite;
}
@keyframes barShimmer {
  0%, 100% { opacity: 0; }
  50% { opacity: 1; }
}

/* ---- COMPONENT GRID ---- */
.ibm-components-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
}
.ibm-comp-card {
  background: var(--ibm-bg-card);
  border: 1px solid var(--ibm-border);
  border-radius: var(--ibm-radius);
  padding: 20px;
  transition: var(--ibm-transition);
}
.ibm-comp-card:hover { border-color: var(--ibm-border-glow); }
.ibm-comp-card-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.ibm-comp-card-title { font-size: 14px; font-weight: 600; display: flex; align-items: center; gap: 8px; }
.ibm-comp-items { display: flex; flex-wrap: wrap; gap: 8px; }
.ibm-comp-item {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 12px; border-radius: 6px;
  font-size: 12px; font-family: 'IBM Plex Mono', monospace;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.06);
  transition: var(--ibm-transition);
  cursor: default;
}
.ibm-comp-item:hover { background: rgba(255,255,255,0.06); }
.ibm-comp-item .dot {
  width: 8px; height: 8px; border-radius: 50%;
  flex-shrink: 0;
}
.ibm-comp-item .dot.online { background: var(--ibm-green); box-shadow: 0 0 6px var(--ibm-green-glow); }
.ibm-comp-item .dot.offline { background: var(--ibm-red); box-shadow: 0 0 6px var(--ibm-red-glow); animation: dotBlink 1s ease-in-out infinite; }
.ibm-comp-counter { font-size: 12px; color: var(--ibm-text-dim); }

/* ---- TABLE ---- */
.ibm-table-wrapper { overflow-x: auto; border-radius: var(--ibm-radius); border: 1px solid var(--ibm-border); }
.ibm-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.ibm-table thead { background: rgba(99,102,241,0.1); }
.ibm-table th {
  text-align: left; padding: 12px 16px;
  font-weight: 600; font-size: 11px;
  text-transform: uppercase; letter-spacing: 0.8px;
  color: var(--ibm-text-dim);
  border-bottom: 1px solid var(--ibm-border);
}
.ibm-table td {
  padding: 10px 16px;
  border-bottom: 1px solid rgba(255,255,255,0.03);
  font-family: 'IBM Plex Mono', monospace;
  color: var(--ibm-text-muted);
}
.ibm-table tbody tr { transition: background 0.2s; }
.ibm-table tbody tr:hover { background: rgba(99,102,241,0.08); }
.ibm-table .status-cell { display: flex; align-items: center; gap: 6px; }
.ibm-table .status-online { color: var(--ibm-green); }
.ibm-table .status-offline { color: var(--ibm-red); font-weight: 600; }

/* ---- TOOLTIP CUSTOM ---- */
.ibm-tooltip {
  position: fixed;
  background: #1e293b;
  border: 1px solid var(--ibm-border-glow);
  border-radius: var(--ibm-radius-sm);
  padding: 12px 16px;
  font-size: 12px;
  color: var(--ibm-text);
  box-shadow: var(--ibm-shadow);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s;
  z-index: 9999;
  max-width: 300px;
}
.ibm-tooltip.show { opacity: 1; }
.ibm-tooltip-title { font-weight: 600; margin-bottom: 6px; font-size: 13px; }
.ibm-tooltip-row { display: flex; justify-content: space-between; gap: 16px; padding: 2px 0; }
.ibm-tooltip-label { color: var(--ibm-text-dim); }
.ibm-tooltip-value { font-weight: 600; font-family: 'IBM Plex Mono', monospace; }

/* ---- NO DATA STATE ---- */
.ibm-no-data {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  min-height: 400px; gap: 16px;
  color: var(--ibm-text-dim);
}
.ibm-no-data-icon { font-size: 48px; opacity: 0.3; }
.ibm-no-data-text { font-size: 15px; font-weight: 500; }
.ibm-no-data-sub { font-size: 12px; }

/* ---- TABS ---- */
.ibm-tabs {
  display: flex; gap: 4px; margin-bottom: 20px;
  background: rgba(255,255,255,0.03);
  border-radius: var(--ibm-radius-sm);
  padding: 4px;
  border: 1px solid var(--ibm-border);
}
.ibm-tab {
  padding: 8px 18px; border-radius: 6px;
  font-size: 13px; font-weight: 500;
  color: var(--ibm-text-dim);
  cursor: pointer;
  transition: var(--ibm-transition);
  border: none; background: none;
}
.ibm-tab:hover { color: var(--ibm-text); background: rgba(255,255,255,0.05); }
.ibm-tab.active {
  background: var(--ibm-blue);
  color: #fff;
  box-shadow: 0 2px 8px var(--ibm-blue-glow);
}
.ibm-tab-content { display: none; }
.ibm-tab-content.active { display: block; animation: fadeIn 0.4s ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ---- RESPONSIVE ---- */
@media (max-width: 768px) {
  .ibm-dashboard { padding: 12px; }
  .ibm-header { flex-direction: column; align-items: flex-start; gap: 12px; }
  .ibm-kpi-row { grid-template-columns: repeat(2, 1fr); }
  .ibm-pools-grid { grid-template-columns: 1fr; }
  .ibm-gauge-container { flex-direction: column; align-items: center; text-align: center; }
  .ibm-kpi-value { font-size: 24px; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
// --- Integração Grafana ---
var __initialPayload = getInitialPayload();
if (__initialPayload) processData(__initialPayload);
window.onDataReceived = function(d) { processData(d); };
window.onInit = function(d) { if (d) processData(d); };

// ===================== UTILIDADES =====================

function formatBytes(bytes, decimals) {
  if (decimals === undefined) decimals = 2;
  if (!bytes || isNaN(bytes) || bytes === 0) return '0 B';
  var k = 1024;
  var sizes = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
  var i = Math.floor(Math.log(Math.abs(bytes)) / Math.log(k));
  if (i >= sizes.length) i = sizes.length - 1;
  return (bytes / Math.pow(k, i)).toFixed(decimals) + ' ' + sizes[i];
}

function getGaugeColor(pct) {
  if (pct >= 90) return '#f43f5e';
  if (pct >= 75) return '#f59e0b';
  return '#10b981';
}

function getHtmlRoot() {
  if (typeof htmlNode !== 'undefined' && htmlNode && typeof htmlNode.querySelector === 'function') {
    return htmlNode;
  }
  return document;
}

function el(id) {
  var root = getHtmlRoot();
  if (root && typeof root.getElementById === 'function') {
    var rootEl = root.getElementById(id);
    if (rootEl) return rootEl;
  }
  return document.getElementById(id);
}

function qsa(selector) {
  var root = getHtmlRoot();
  if (root && typeof root.querySelectorAll === 'function') return root.querySelectorAll(selector);
  return document.querySelectorAll(selector);
}

function getInitialPayload() {
  if (typeof data !== 'undefined' && data) return data;
  if (typeof panelData !== 'undefined' && panelData) return panelData;
  if (typeof htmlGraphics !== 'undefined' && htmlGraphics && htmlGraphics.data) return htmlGraphics.data;
  return null;
}

function safeText(v) { return (v === null || v === undefined || v === '') ? '--' : String(v); }

function extractGrafanaFrames(payload) {
  if (!payload) return [];

  if (Array.isArray(payload)) return payload;
  if (payload.series && Array.isArray(payload.series)) return payload.series;

  if (payload.data) {
    if (Array.isArray(payload.data)) return payload.data;
    if (payload.data.series && Array.isArray(payload.data.series)) return payload.data.series;
    if (payload.data.data && Array.isArray(payload.data.data)) return payload.data.data;
  }

  if (payload.results && typeof payload.results === 'object') {
    var rFrames = [];
    for (var rk in payload.results) {
      if (!payload.results.hasOwnProperty(rk)) continue;
      var r = payload.results[rk];
      if (!r) continue;
      if (Array.isArray(r.series)) rFrames = rFrames.concat(r.series);
      if (Array.isArray(r.frames)) rFrames = rFrames.concat(r.frames);
    }
    if (rFrames.length) return rFrames;
  }

  if (payload.response && payload.response.results && typeof payload.response.results === 'object') {
    var rrFrames = [];
    for (var rrk in payload.response.results) {
      if (!payload.response.results.hasOwnProperty(rrk)) continue;
      var rr = payload.response.results[rrk];
      if (!rr) continue;
      if (Array.isArray(rr.series)) rrFrames = rrFrames.concat(rr.series);
      if (Array.isArray(rr.frames)) rrFrames = rrFrames.concat(rr.frames);
      if (Array.isArray(rr.data)) rrFrames = rrFrames.concat(rr.data);
    }
    if (rrFrames.length) return rrFrames;
  }

  return [];
}

// ===================== TABS =====================

var tabsInitialized = false;
function initTabs() {
  if (tabsInitialized) return;
  var tabs = qsa('.ibm-tab');
  if (!tabs || tabs.length === 0) return;

  tabs.forEach(function(tab) {
    tab.addEventListener('click', function() {
      tabs.forEach(function(t) { t.classList.remove('active'); });
      tab.classList.add('active');
      qsa('.ibm-tab-content').forEach(function(c) { c.classList.remove('active'); });
      var target = el('tab-' + tab.getAttribute('data-tab'));
      if (target) target.classList.add('active');
    });
  });

  tabsInitialized = true;
}

// ===================== TOOLTIP =====================

function getTooltip() { return el('ibmTooltip'); }
function showTooltip(evt, html) {
  var tooltip = getTooltip();
  if (!tooltip) return;
  tooltip.innerHTML = html;
  tooltip.classList.add('show');
  tooltip.style.left = (evt.clientX + 12) + 'px';
  tooltip.style.top = (evt.clientY + 12) + 'px';
}
function hideTooltip() {
  var tooltip = getTooltip();
  if (tooltip) tooltip.classList.remove('show');
}
document.addEventListener('mousemove', function(e) {
  var tooltip = getTooltip();
  if (tooltip && tooltip.classList.contains('show')) {
    tooltip.style.left = (e.clientX + 12) + 'px';
    tooltip.style.top = (e.clientY + 12) + 'px';
  }
});

// ===================== SVG GAUGE =====================

function createGaugeSVG(percent, label) {
  var pct = Math.min(100, Math.max(0, percent || 0));
  var r = 45;
  var circ = 2 * Math.PI * r;
  var offset = circ - (pct / 100) * circ;
  var color = getGaugeColor(pct);
  return '<svg class="ibm-gauge-svg" viewBox="0 0 120 120">' +
    '<circle class="ibm-gauge-bg" cx="60" cy="60" r="' + r + '"/>' +
    '<circle class="ibm-gauge-fill" cx="60" cy="60" r="' + r + '" ' +
    'stroke="' + color + '" stroke-dasharray="' + circ + '" stroke-dashoffset="' + offset + '" ' +
    'transform="rotate(-90 60 60)" style="filter: drop-shadow(0 0 6px ' + color + '40);"/>' +
    '<text class="ibm-gauge-text" x="60" y="58">' + pct.toFixed(1) + '%</text>' +
    '<text class="ibm-gauge-sublabel" x="60" y="73">' + (label || 'USADO') + '</text></svg>';
}

// ===================== PROCESSAMENTO =====================

function processData(grafanaData, attempt) {
  if (attempt === undefined) attempt = 0;
  if (!el('ibmDashboard')) {
    if (attempt < 30) {
      setTimeout(function() { processData(grafanaData, attempt + 1); }, 100);
    }
    return;
  }

  initTabs();

  var lastUpdate = el('lastUpdate');
  if (lastUpdate) lastUpdate.textContent = new Date().toLocaleTimeString('pt-BR');
  try {
    var frames = extractGrafanaFrames(grafanaData);
    if ((!frames || frames.length === 0) && attempt === 0) {
      if (console && console.warn) console.warn('IBM Dashboard: nenhum frame extraído do payload', grafanaData);
    }
    var storage = { pools: [], hosts: [], drives: [], enclosures: [], canisters: [], psus: [], volumes: [] };
    parseGenericSeries(frames, storage);
    renderKPIs(storage);
    renderPools(storage);
    renderHosts(storage);
    renderHardware(storage);
    renderVolumes(storage);
  } catch (e) {
    if (console && console.error) console.error('Erro ao processar dashboard:', e);
  }
}

// ===================== PARSER GENÉRICO =====================

function getLastNonNull(arr) {
  if (!arr || !arr.length) return null;
  for (var i = arr.length - 1; i >= 0; i--) {
    var v = arr[i];
    if (v !== null && v !== undefined) return v;
  }
  return null;
}

function objToArr(map) {
  var arr = [];
  for (var key in map) {
    if (map.hasOwnProperty(key)) arr.push(map[key]);
  }
  return arr;
}

function getLastValueFromFieldValues(values) {
  if (!values) return null;

  if (Array.isArray(values)) {
    return getLastNonNull(values);
  }

  if (typeof values.length === 'number' && typeof values.get === 'function') {
    for (var i = values.length - 1; i >= 0; i--) {
      var v = values.get(i);
      if (v !== null && v !== undefined) return v;
    }
  }

  return null;
}

function getPoolNameFromRef(ref) {
  var m = String(ref || '').match(/^([^:]+):/);
  return m ? m[1] : String(ref || '');
}

function getQuotedName(text, keyWord) {
  var pattern = new RegExp(keyWord + '\\s*:\\s*"([^"]+)"', 'i');
  var m = String(text || '').match(pattern);
  return m ? m[1] : null;
}

function applyMetricToMaps(metricKey, itemLabel, value, maps) {
  if (!metricKey) return;

  var poolMatch = metricKey.match(/^storage\.pool\.(\w+)\["?([^"\]]+)"?\]/i);
  if (poolMatch) {
    var poolName = getPoolNameFromRef(poolMatch[2]);
    if (!maps.poolMap[poolName]) maps.poolMap[poolName] = { name: poolName };
    maps.poolMap[poolName][poolMatch[1]] = value;
    return;
  }

  var hostMatch = metricKey.match(/^lshost\.(\w+)\[(.+?)\]$/i);
  if (hostMatch) {
    var hostId = String(hostMatch[2]).replace(/^"|"$/g, '');
    if (!maps.hostMap[hostId]) maps.hostMap[hostId] = { id: hostId, name: hostId };
    maps.hostMap[hostId][hostMatch[1]] = value;
    var hostNameFromLabel = getQuotedName(itemLabel, 'Host');
    if (hostNameFromLabel) maps.hostMap[hostId].name = hostNameFromLabel;
    return;
  }

  var driveMatch = metricKey.match(/^drive\.(\w+)\["?([^"\]]+)"?\]/i);
  if (driveMatch) {
    var driveId = driveMatch[2];
    if (!maps.driveMap[driveId]) maps.driveMap[driveId] = { id: driveId };
    maps.driveMap[driveId][driveMatch[1]] = value;
    var driveName = getQuotedName(itemLabel, 'disco');
    if (driveName) maps.driveMap[driveId].mdisk_name = driveName;
    return;
  }

  var encMatch = metricKey.match(/^enclosure\.(\w+)\["?([^"\]]+)"?\]/i);
  if (encMatch) {
    var encId = encMatch[2];
    if (!maps.encMap[encId]) maps.encMap[encId] = { id: encId };
    maps.encMap[encId][encMatch[1]] = value;
    return;
  }

  var canMatch = metricKey.match(/^canister\.(\w+)\["?([^"\]]+)"?\]/i);
  if (canMatch) {
    var canId = canMatch[2];
    if (!maps.canMap[canId]) maps.canMap[canId] = { id: canId };
    maps.canMap[canId][canMatch[1]] = value;
    var canName = getQuotedName(itemLabel, 'Canister');
    if (canName) maps.canMap[canId].node_name = canName;
    return;
  }

  var psuMatch = metricKey.match(/^psu\.(\w+)\["?([^"\]]+)"?\]/i);
  if (psuMatch) {
    var psuId = psuMatch[2];
    if (!maps.psuMap[psuId]) maps.psuMap[psuId] = { id: psuId };
    maps.psuMap[psuId][psuMatch[1]] = value;
    return;
  }

  var volMatch = metricKey.match(/^vdisk\.(\w+)\["?([^"\]]+)"?\]/i);
  if (volMatch) {
    var volId = volMatch[2];
    if (!maps.volMap[volId]) maps.volMap[volId] = { id: volId, name: volId };
    maps.volMap[volId][volMatch[1]] = value;
    var volNameFromLabel = getQuotedName(itemLabel, 'Volume');
    if (volNameFromLabel) maps.volMap[volId].name = volNameFromLabel;
  }
}

function parseGenericSeries(frames, storage) {
  var poolMap = {}, hostMap = {}, driveMap = {}, encMap = {}, canMap = {}, psuMap = {}, volMap = {};
  var maps = {
    poolMap: poolMap,
    hostMap: hostMap,
    driveMap: driveMap,
    encMap: encMap,
    canMap: canMap,
    psuMap: psuMap,
    volMap: volMap
  };

  if (!frames) frames = [];

  frames.forEach(function(frame) {
    if (frame && frame.schema && frame.data && frame.schema.fields && frame.data.values) {
      var fields = frame.schema.fields;
      var columns = frame.data.values;

      for (var i = 0; i < fields.length; i++) {
        var field = fields[i] || {};
        if (field.type === 'time') continue;

        var colValues = columns[i];
        var lastVal = getLastValueFromFieldValues(colValues);
        var metricKey = (field.labels && field.labels.item_key) || field.name || '';
        var itemLabel = (field.labels && field.labels.item) || '';
        applyMetricToMaps(metricKey, itemLabel, lastVal, maps);
      }
      return;
    }

    var seriesName = (frame && frame.name) || '';
    var fields = (frame && frame.fields) || [];
    fields.forEach(function(field) {
      if (!field || field.type === 'time') return;
      var lastVal = getLastValueFromFieldValues(field.values);
      var metricKey = (field.labels && field.labels.item_key) || field.name || seriesName;
      var itemLabel = (field.labels && field.labels.item) || '';
      applyMetricToMaps(metricKey, itemLabel, lastVal, maps);
    });
  });

  storage.pools = objToArr(poolMap);
  storage.hosts = objToArr(hostMap);
  storage.drives = objToArr(driveMap);
  storage.enclosures = objToArr(encMap);
  storage.canisters = objToArr(canMap);
  storage.psus = objToArr(psuMap);
  storage.volumes = objToArr(volMap);

  var storageName = el('storageName');
  if (storageName && frames.length > 0) {
    var hostLabel = null;
    for (var f = 0; f < frames.length && !hostLabel; f++) {
      var fieldsToInspect = null;
      if (frames[f] && frames[f].schema && frames[f].schema.fields) fieldsToInspect = frames[f].schema.fields;
      else if (frames[f] && frames[f].fields) fieldsToInspect = frames[f].fields;

      if (!fieldsToInspect) continue;

      for (var j = 0; j < fieldsToInspect.length; j++) {
        var lf = fieldsToInspect[j];
        if (lf && lf.labels && lf.labels.host) {
          hostLabel = lf.labels.host;
          break;
        }
      }
    }
    if (hostLabel) storageName.textContent = hostLabel;
  }
  storage.volumes = objToArr(volMap);
}

// ===================== RENDER KPIs =====================

function renderKPIs(storage) {
  var offlineCount = function(arr) { return arr.filter(function(i) { return i.status === 0 || i.status === '0'; }).length; };
  var totalAlerts = offlineCount(storage.pools) + offlineCount(storage.hosts) + offlineCount(storage.drives) +
    offlineCount(storage.volumes) + offlineCount(storage.canisters) + offlineCount(storage.psus);

  var kpiPoolsVal = el('kpiPoolsVal');
  var kpiPoolsSub = el('kpiPoolsSub');
  var kpiVolumesVal = el('kpiVolumesVal');
  var kpiVolumesSub = el('kpiVolumesSub');
  var kpiHostsVal = el('kpiHostsVal');
  var kpiHostsSub = el('kpiHostsSub');
  var kpiDrivesVal = el('kpiDrivesVal');
  var kpiDrivesSub = el('kpiDrivesSub');
  var kpiEnclosuresVal = el('kpiEnclosuresVal');
  var kpiEnclosuresSub = el('kpiEnclosuresSub');
  var kpiAlertsVal = el('kpiAlertsVal');
  var kpiAlertsSub = el('kpiAlertsSub');
  var kpiAlerts = el('kpiAlerts');

  if (kpiPoolsVal) kpiPoolsVal.textContent = storage.pools.length || '--';
  if (kpiPoolsSub) kpiPoolsSub.textContent = offlineCount(storage.pools) > 0 ? offlineCount(storage.pools) + ' offline!' : 'todos online';
  if (kpiVolumesVal) kpiVolumesVal.textContent = storage.volumes.length || '--';
  if (kpiVolumesSub) kpiVolumesSub.textContent = offlineCount(storage.volumes) > 0 ? offlineCount(storage.volumes) + ' offline!' : 'todos online';
  if (kpiHostsVal) kpiHostsVal.textContent = storage.hosts.length || '--';
  if (kpiHostsSub) kpiHostsSub.textContent = offlineCount(storage.hosts) > 0 ? offlineCount(storage.hosts) + ' offline!' : 'todos online';
  if (kpiDrivesVal) kpiDrivesVal.textContent = storage.drives.length || '--';
  if (kpiDrivesSub) kpiDrivesSub.textContent = offlineCount(storage.drives) > 0 ? offlineCount(storage.drives) + ' offline!' : 'todos online';
  if (kpiEnclosuresVal) kpiEnclosuresVal.textContent = storage.enclosures.length || '--';
  if (kpiEnclosuresSub) kpiEnclosuresSub.textContent = 'monitorados';

  if (kpiAlertsVal) {
    kpiAlertsVal.textContent = totalAlerts;
    kpiAlertsVal.className = 'ibm-kpi-value ' + (totalAlerts === 0 ? 'green' : 'red');
  }
  if (kpiAlertsSub) kpiAlertsSub.textContent = totalAlerts === 0 ? 'tudo operacional ✓' : 'componentes offline!';
  if (kpiAlerts) kpiAlerts.className = 'ibm-kpi-card ' + (totalAlerts === 0 ? 'green' : 'red');

  var gs = el('globalStatus');
  if (gs) {
    var statusText = gs.querySelector('span');
    if (totalAlerts > 0) {
      gs.className = 'ibm-status-badge offline';
      if (statusText) statusText.textContent = totalAlerts + ' Alertas';
    } else {
      gs.className = 'ibm-status-badge';
      if (statusText) statusText.textContent = 'Operacional';
    }
  }
}

// ===================== RENDER POOLS =====================

function renderPools(storage) {
  var grid = el('poolsGrid');
  if (!grid) return;
  if (storage.pools.length === 0) {
    grid.innerHTML = '<div class="ibm-no-data"><div class="ibm-no-data-icon">📊</div>' +
      '<div class="ibm-no-data-text">Nenhum dado de Pool recebido</div>' +
      '<div class="ibm-no-data-sub">Verifique as queries no painel Grafana</div></div>';
    return;
  }
  var html = '';
  storage.pools.forEach(function(pool) {
    var total = parseFloat(pool.capacity) || 0;
    var used = parseFloat(pool.used) || parseFloat(pool.used_capacity) || 0;
    var free = parseFloat(pool.free_capacity) || (total - used);
    var virtualCap = parseFloat(pool.virtual_capacity) || 0;
    var pct = total > 0 ? (used / total) * 100 : 0;
    var isOnline = pool.status !== 0 && pool.status !== '0';
    var barColor = getGaugeColor(pct);

    html += '<div class="ibm-pool-card"><div class="ibm-pool-header">' +
      '<div class="ibm-pool-name">' + safeText(pool.name) + '</div>' +
      '<div class="ibm-pool-status ' + (isOnline ? 'online' : 'offline') + '">' + (isOnline ? 'Online' : 'Offline') + '</div></div>' +
      '<div class="ibm-gauge-container">' + createGaugeSVG(pct, 'USADO') +
      '<div class="ibm-pool-details">' +
      '<div class="ibm-pool-detail-row"><span class="ibm-pool-detail-label">Total</span><span class="ibm-pool-detail-value">' + formatBytes(total) + '</span></div>' +
      '<div class="ibm-pool-detail-row"><span class="ibm-pool-detail-label">Usado</span><span class="ibm-pool-detail-value" style="color:' + barColor + '">' + formatBytes(used) + '</span></div>' +
      '<div class="ibm-pool-detail-row"><span class="ibm-pool-detail-label">Livre</span><span class="ibm-pool-detail-value" style="color:#10b981">' + formatBytes(free) + '</span></div>' +
      '<div class="ibm-pool-detail-row"><span class="ibm-pool-detail-label">Virtual</span><span class="ibm-pool-detail-value">' + formatBytes(virtualCap) + '</span></div>' +
      '<div class="ibm-pool-detail-row"><span class="ibm-pool-detail-label">MDisks / VDisks</span><span class="ibm-pool-detail-value">' + (pool.mdisk_count||'--') + ' / ' + (pool.vdisk_count||'--') + '</span></div>' +
      '</div></div>' +
      '<div class="ibm-pool-bar-container"><div class="ibm-pool-bar-labels"><span>Utilização</span><span style="color:' + barColor + ';font-weight:600">' + pct.toFixed(1) + '%</span></div>' +
      '<div class="ibm-pool-bar"><div class="ibm-pool-bar-fill" style="width:' + pct + '%;background:linear-gradient(90deg,' + barColor + ',' + barColor + 'aa);"></div></div></div></div>';
  });
  grid.innerHTML = html;
}

// ===================== RENDER HOSTS =====================

function renderHosts(storage) {
  var tbody = el('hostsBody');
  if (!tbody) return;
  if (storage.hosts.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;color:var(--ibm-text-dim);padding:40px;">Nenhum dado de Host recebido</td></tr>';
    return;
  }
  var html = '';
  storage.hosts.forEach(function(host) {
    var isOnline = host.status !== 0 && host.status !== '0';
    html += '<tr><td style="font-weight:600;color:var(--ibm-text)">' + safeText(host.name || host.id) + '</td>' +
      '<td><div class="status-cell"><span class="dot ' + (isOnline?'online':'offline') + '" style="width:8px;height:8px;border-radius:50%;display:inline-block"></span>' +
      '<span class="' + (isOnline?'status-online':'status-offline') + '">' + (isOnline?'Online':'Offline') + '</span></div></td>' +
      '<td>' + (host.port_count||'--') + '</td><td>' + (host.protocol||'--') + '</td>' +
      '<td>' + (host.cluster_name||'--') + '</td><td>' + (host.iogrp_count||'--') + '</td></tr>';
  });
  tbody.innerHTML = html;
}

// ===================== RENDER HARDWARE =====================

function renderHardware(storage) {
  renderItems('enclosureItems', 'enclosureCounter', storage.enclosures, function(e) { return 'Enc #' + (e.id||'?'); });
  renderItems('canisterItems', 'canisterCounter', storage.canisters, function(c) { return c.node_name || ('Can #' + (c.id||'?')); });
  renderItems('driveItems', 'driveCounter', storage.drives, function(d) { return d.mdisk_name || ('Drive #' + (d.id||'?')); });
  renderItems('psuItems', 'psuCounter', storage.psus, function(p) { return 'PSU #' + (p.PSU_id||p.id||'?'); });
}

function renderItems(cId, countId, items, labelFn) {
  var c = el(cId), cnt = el(countId);
  if (!c || !cnt) return;
  if (!items || items.length === 0) { c.innerHTML = '<div style="color:var(--ibm-text-dim);font-size:12px;">Sem dados</div>'; cnt.textContent = '--'; return; }
  var on = items.filter(function(i) { return i.status !== 0 && i.status !== '0'; }).length;
  cnt.textContent = on + '/' + items.length + ' online';
  var html = '';
  items.forEach(function(item) {
    var isOn = item.status !== 0 && item.status !== '0';
    html += '<div class="ibm-comp-item"><span class="dot ' + (isOn?'online':'offline') + '"></span><span>' + labelFn(item) + '</span></div>';
  });
  c.innerHTML = html;
}

// ===================== RENDER VOLUMES =====================

function renderVolumes(storage) {
  var tbody = el('volumesBody');
  if (!tbody) return;
  if (storage.volumes.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;color:var(--ibm-text-dim);padding:40px;">Nenhum dado de Volume recebido</td></tr>';
    return;
  }
  var html = '';
  storage.volumes.forEach(function(vol) {
    var isOnline = vol.status !== 0 && vol.status !== '0';
    html += '<tr><td style="font-weight:600;color:var(--ibm-text)">' + safeText(vol.name||vol.id) + '</td>' +
      '<td><div class="status-cell"><span class="dot ' + (isOnline?'online':'offline') + '" style="width:8px;height:8px;border-radius:50%;display:inline-block"></span>' +
      '<span class="' + (isOnline?'status-online':'status-offline') + '">' + (isOnline?'Online':'Offline') + '</span></div></td>' +
      '<td>' + formatBytes(parseFloat(vol.capacity_bytes||vol.capacity||0)) + '</td>' +
      '<td>' + (vol.mdisk_grp_name||vol.pool||'--') + '</td>' +
      '<td>' + (vol.snapshot_count||vol.snapshots||'0') + '</td>' +
      '<td>' + (vol.volume_group_name||vol.volgroup||'--') + '</td></tr>';
  });
  tbody.innerHTML = html;
}

