/* Widget isolado: Problems em tempo real */

.ibm-problems-dashboard {
  font-family: 'IBM Plex Sans', -apple-system, sans-serif;
  background: var(--ibm-bg-deep, #0f172a);
  color: var(--ibm-text, #f8fafc);
  padding: 16px;
  min-height: 100%;
}

.ibm-problems-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--ibm-border, rgba(255,255,255,.1));
}

.ibm-problems-header h2 {
  font-size: 18px;
  margin: 0;
  font-weight: 600;
}

.ibm-problems-sub,
.ibm-problems-updated {
  font-size: 12px;
  color: var(--ibm-text-dim, #64748b);
}

.ibm-problems-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
  margin-bottom: 16px;
}

.ibm-problem-kpi {
  background: var(--ibm-bg-card, rgba(15, 23, 42, .7));
  border: 1px solid var(--ibm-border, rgba(255,255,255,.1));
  border-radius: 10px;
  padding: 12px;
  cursor: pointer;
  transition: border-color .2s ease, transform .2s ease;
}

.ibm-problem-kpi:hover {
  border-color: var(--ibm-accent, #6366f1);
  transform: translateY(-1px);
}

.ibm-problem-kpi.active {
  border-color: var(--ibm-accent, #6366f1);
  box-shadow: 0 0 0 1px rgba(99,102,241,.4) inset;
}

.ibm-problem-kpi .label {
  font-size: 11px;
  color: var(--ibm-text-dim, #64748b);
  text-transform: uppercase;
  letter-spacing: .7px;
  margin-bottom: 6px;
}

.ibm-problem-kpi .value {
  font-size: 24px;
  font-weight: 700;
  font-family: 'IBM Plex Mono', monospace;
}

.ibm-problem-kpi.critical .value { color: #f43f5e; }
.ibm-problem-kpi.high .value { color: #f59e0b; }
.ibm-problem-kpi.warning .value { color: #f59e0b; }
.ibm-problem-kpi.total .value { color: #3b82f6; }

.ibm-problems-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  gap: 10px;
}

.ibm-problems-filter-info {
  font-size: 12px;
  color: var(--ibm-text-dim, #64748b);
}

.ibm-problems-clear-btn {
  border: 1px solid var(--ibm-border, rgba(255,255,255,.1));
  background: rgba(255,255,255,.03);
  color: var(--ibm-text, #f8fafc);
  padding: 6px 10px;
  border-radius: 8px;
  font-size: 12px;
  cursor: pointer;
}

.ibm-problems-clear-btn:hover {
  background: rgba(255,255,255,.07);
}

.ibm-problems-table-wrap {
  border: 1px solid var(--ibm-border, rgba(255,255,255,.1));
  border-radius: 10px;
  overflow-x: auto;
}

.ibm-problems-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.ibm-problems-table thead {
  background: rgba(99,102,241,.1);
}

.ibm-problems-table th,
.ibm-problems-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255,255,255,.04);
}

.ibm-problems-table th {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .7px;
  color: var(--ibm-text-dim, #64748b);
}

.ibm-problems-table td {
  color: var(--ibm-text-muted, #94a3b8);
}

.ibm-problems-table td.empty {
  text-align: center;
  color: var(--ibm-text-dim, #64748b);
  padding: 26px 12px;
}

.ibm-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 600;
}

.ibm-pill.sev-critical { background: rgba(244,63,94,.16); color: #f43f5e; }
.ibm-pill.sev-high { background: rgba(245,158,11,.16); color: #f59e0b; }
.ibm-pill.sev-warning { background: rgba(245,158,11,.16); color: #f59e0b; }
.ibm-pill.sev-info { background: rgba(59,130,246,.16); color: #3b82f6; }

.ibm-status-open { color: #f43f5e; font-weight: 600; }
.ibm-status-closed { color: #10b981; font-weight: 600; }

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
// --- Integração Grafana ---
var __initialPayload = getInitialPayload();
if (__initialPayload) processProblemsData(__initialPayload);
window.onDataReceived = function(d) { processProblemsData(d); };
window.onInit = function(d) { if (d) processProblemsData(d); };

var problemsUIState = {
  allProblems: [],
  filter: 'all'
};
var problemsInteractionsBound = false;

function getHtmlRoot() {
  if (typeof htmlNode !== 'undefined' && htmlNode && typeof htmlNode.querySelector === 'function') return htmlNode;
  return document;
}

function el(id) {
  var root = getHtmlRoot();
  if (root && typeof root.getElementById === 'function') {
    var found = root.getElementById(id);
    if (found) return found;
  }
  return document.getElementById(id);
}

function qsa(selector) {
  var root = getHtmlRoot();
  if (root && typeof root.querySelectorAll === 'function') return root.querySelectorAll(selector);
  return document.querySelectorAll(selector);
}

function getInitialPayload() {
  if (typeof data !== 'undefined' && data) return data;
  if (typeof panelData !== 'undefined' && panelData) return panelData;
  if (typeof htmlGraphics !== 'undefined' && htmlGraphics && htmlGraphics.data) return htmlGraphics.data;
  return null;
}

function extractGrafanaFrames(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload;
  if (payload.series && Array.isArray(payload.series)) return payload.series;

  if (payload.data) {
    if (Array.isArray(payload.data)) return payload.data;
    if (payload.data.series && Array.isArray(payload.data.series)) return payload.data.series;
    if (payload.data.data && Array.isArray(payload.data.data)) return payload.data.data;
  }

  if (payload.results && typeof payload.results === 'object') {
    var frames = [];
    for (var k in payload.results) {
      if (!payload.results.hasOwnProperty(k)) continue;
      var r = payload.results[k];
      if (!r) continue;
      if (Array.isArray(r.series)) frames = frames.concat(r.series);
      if (Array.isArray(r.frames)) frames = frames.concat(r.frames);
      if (Array.isArray(r.data)) frames = frames.concat(r.data);
    }
    return frames;
  }

  return [];
}

function getLastNonNull(values) {
  if (!values) return null;

  if (Array.isArray(values)) {
    for (var i = values.length - 1; i >= 0; i--) {
      if (values[i] !== null && values[i] !== undefined) return values[i];
    }
    return null;
  }

  if (typeof values.length === 'number' && typeof values.get === 'function') {
    for (var j = values.length - 1; j >= 0; j--) {
      var v = values.get(j);
      if (v !== null && v !== undefined) return v;
    }
  }

  return null;
}

function valueAt(values, index) {
  if (!values) return null;
  if (Array.isArray(values)) return values[index];
  if (typeof values.get === 'function') return values.get(index);
  return null;
}

function isTimeField(fieldName, fieldType) {
  if (fieldType === 'time') return true;
  var name = String(fieldName || '').toLowerCase();
  return name === 'time' || name === 'timestamp' || name === 'clock' || name === 'lastchange';
}

function normalizeSeverity(raw) {
  var t = String(raw === null || raw === undefined ? '' : raw).toLowerCase();
  if (!t) return 'warning';

  if (t.indexOf('disaster') >= 0 || t.indexOf('critical') >= 0 || t === '5' || t === '4') return 'critical';
  if (t.indexOf('high') >= 0 || t === '3') return 'high';
  if (t.indexOf('warning') >= 0 || t.indexOf('average') >= 0 || t === '2' || t === '1') return 'warning';
  return 'info';
}

function severityLabel(sev) {
  if (sev === 'critical') return 'Critical';
  if (sev === 'high') return 'High';
  if (sev === 'warning') return 'Warning';
  return 'Info';
}

function severityClass(sev) {
  if (sev === 'critical') return 'sev-critical';
  if (sev === 'high') return 'sev-high';
  if (sev === 'warning') return 'sev-warning';
  return 'sev-info';
}

function filterLabel(filter) {
  if (filter === 'critical') return 'Crítico';
  if (filter === 'high') return 'Alto';
  if (filter === 'warning') return 'Warning';
  return 'Todos';
}

function bindProblemsInteractions() {
  if (problemsInteractionsBound) return;

  var cards = qsa('.ibm-problem-kpi[data-sev]');
  if (cards && cards.length) {
    cards.forEach(function(card) {
      card.addEventListener('click', function() {
        var sev = card.getAttribute('data-sev') || 'all';
        problemsUIState.filter = sev;
        renderProblems(problemsUIState.allProblems);
      });
    });
  }

  var clearBtn = el('clearProblemsFilter');
  if (clearBtn) {
    clearBtn.addEventListener('click', function() {
      problemsUIState.filter = 'all';
      renderProblems(problemsUIState.allProblems);
    });
  }

  problemsInteractionsBound = true;
}

function normalizeStatus(raw) {
  var t = String(raw === null || raw === undefined ? '' : raw).toLowerCase();
  if (!t) return 'unknown';
  if (t === '0' || t.indexOf('ok') >= 0 || t.indexOf('resolved') >= 0 || t.indexOf('close') >= 0) return 'closed';
  if (t === '1' || t.indexOf('problem') >= 0 || t.indexOf('open') >= 0 || t.indexOf('ativo') >= 0 || t.indexOf('active') >= 0) return 'open';
  return 'unknown';
}

function parseProblemsFromFrames(frames) {
  var problems = [];

  frames.forEach(function(frame) {
    if (!frame) return;

    if (frame.schema && frame.data && frame.schema.fields && frame.data.values) {
      var schemaFields = frame.schema.fields;
      var cols = frame.data.values;

      var rowsCount = 0;
      for (var i = 0; i < cols.length; i++) {
        if (cols[i] && typeof cols[i].length === 'number' && cols[i].length > rowsCount) rowsCount = cols[i].length;
      }

      var hasTabularSignals = false;
      schemaFields.forEach(function(f) {
        var n = String((f && f.name) || '').toLowerCase();
        if (n.indexOf('problem') >= 0 || n.indexOf('severity') >= 0 || n.indexOf('trigger') >= 0 || n.indexOf('host') >= 0) {
          hasTabularSignals = true;
        }
      });

      if (hasTabularSignals && rowsCount > 0) {
        for (var row = 0; row < rowsCount; row++) {
          var p = { severity: 'warning', host: '--', name: '--', status: 'unknown', updatedAt: '--' };
          var hasStatusField = false;

          for (var sf = 0; sf < schemaFields.length; sf++) {
            var field = schemaFields[sf] || {};
            var fieldName = String(field.name || '');
            if (isTimeField(fieldName, field.type)) continue;
            var lower = fieldName.toLowerCase();
            var v = valueAt(cols[sf], row);
            var txt = (v === null || v === undefined) ? '' : String(v);

            if (lower.indexOf('severity') >= 0 || lower.indexOf('priority') >= 0) p.severity = normalizeSeverity(txt);
            else if (lower === 'host' || lower.indexOf('host') >= 0) p.host = txt || p.host;
            else if (lower.indexOf('problem') >= 0 || lower.indexOf('name') >= 0 || lower.indexOf('trigger') >= 0 || lower.indexOf('description') >= 0) p.name = txt || p.name;
            else if (lower.indexOf('status') >= 0 || lower.indexOf('state') >= 0 || lower.indexOf('value') >= 0) {
              hasStatusField = true;
              p.status = normalizeStatus(txt);
            }
            else if (lower.indexOf('time') >= 0 || lower.indexOf('clock') >= 0 || lower.indexOf('change') >= 0 || lower.indexOf('update') >= 0) p.updatedAt = txt || p.updatedAt;
          }

          var hasRealName = p.name !== '--' && String(p.name).toLowerCase() !== 'problems';
          if (hasStatusField && p.status === 'open' && (hasRealName || p.host !== '--')) {
            problems.push(p);
          }
        }
        return;
      }
    }

    var fields = frame.fields || [];
    fields.forEach(function(field) {
      if (!field || field.type === 'time') return;
      var metricName = String(field.name || '').toLowerCase();
      var labels = field.labels || {};
      var lastValue = getLastNonNull(field.values);
      var hasProblemIdentity = !!(labels.problem || labels.trigger || labels.eventid);

      if ((metricName.indexOf('problem') >= 0 || metricName.indexOf('trigger') >= 0 || labels.problem || labels.trigger) && hasProblemIdentity) {
        var p = {
          severity: normalizeSeverity(labels.severity || labels.priority || labels.level || 'warning'),
          host: labels.host || '--',
          name: labels.problem || labels.trigger || field.name || '--',
          status: normalizeStatus(lastValue),
          updatedAt: '--'
        };
        if (p.status === 'open') problems.push(p);
      }
    });
  });

  return problems;
}

function renderProblems(problems) {
  var kpiCritical = el('kpiCritical');
  var kpiHigh = el('kpiHigh');
  var kpiWarning = el('kpiWarning');
  var kpiTotal = el('kpiTotal');
  var tbody = el('problemsTbody');
  var filterInfo = el('problemsFilterInfo');

  if (!tbody) return;

  problemsUIState.allProblems = Array.isArray(problems) ? problems : [];
  var allProblems = problemsUIState.allProblems;
  var activeFilter = problemsUIState.filter || 'all';
  var filteredProblems = allProblems.filter(function(p) {
    return activeFilter === 'all' ? true : p.severity === activeFilter;
  });

  var critical = allProblems.filter(function(p) { return p.severity === 'critical'; }).length;
  var high = allProblems.filter(function(p) { return p.severity === 'high'; }).length;
  var warning = allProblems.filter(function(p) { return p.severity === 'warning'; }).length;

  if (kpiCritical) kpiCritical.textContent = critical;
  if (kpiHigh) kpiHigh.textContent = high;
  if (kpiWarning) kpiWarning.textContent = warning;
  if (kpiTotal) kpiTotal.textContent = allProblems.length;

  if (filterInfo) {
    filterInfo.textContent = 'Filtro: ' + filterLabel(activeFilter) + ' (' + filteredProblems.length + ')';
  }

  var cards = qsa('.ibm-problem-kpi[data-sev]');
  if (cards && cards.length) {
    cards.forEach(function(card) {
      if ((card.getAttribute('data-sev') || 'all') === activeFilter) card.classList.add('active');
      else card.classList.remove('active');
    });
  }

  if (!filteredProblems.length) {
    tbody.innerHTML = '<tr><td colspan="5" class="empty">Sem problems ativos para o filtro atual.</td></tr>';
    return;
  }

  filteredProblems.sort(function(a, b) {
    var weight = { critical: 0, high: 1, warning: 2, info: 3 };
    return (weight[a.severity] || 99) - (weight[b.severity] || 99);
  });

  var html = '';
  filteredProblems.forEach(function(p) {
    html += '<tr>' +
      '<td><span class="ibm-pill ' + severityClass(p.severity) + '">' + severityLabel(p.severity) + '</span></td>' +
      '<td>' + (p.host || '--') + '</td>' +
      '<td>' + (p.name || '--') + '</td>' +
      '<td class="ibm-status-open">Open</td>' +
      '<td>' + (p.updatedAt || '--') + '</td>' +
      '</tr>';
  });
  tbody.innerHTML = html;
}

function processProblemsData(grafanaData, attempt) {
  if (attempt === undefined) attempt = 0;

  if (!el('ibmProblemsDashboard')) {
    if (attempt < 30) {
      setTimeout(function() { processProblemsData(grafanaData, attempt + 1); }, 100);
    }
    return;
  }

  try {
    bindProblemsInteractions();

    var frames = extractGrafanaFrames(grafanaData);
    var problems = parseProblemsFromFrames(frames);

    var updated = el('problemsUpdatedAt');
    if (updated) updated.textContent = new Date().toLocaleTimeString('pt-BR');

    var source = el('problemsSource');
    if (source) source.textContent = problems.length ? (problems.length + ' evento(s) ativo(s)') : 'Sem eventos ativos';

    renderProblems(problems);
  } catch (e) {
    if (console && console.error) console.error('Erro ao processar widget Problems:', e);
  }
}
